<String> SLOTS = List.of("description", "catalog_id", "quantity", "unit", "amount", "amount_kind", "currency", "purpose"); static final String POLICY_VERSION = "nl-demo-1"; enum Status { ALLOWED, DENIED, NEEDS_APPROVAL, NEEDS_INFO } enum AmountKind { UNIT_PRICE, UNIT_CAP } record Employee(String id, boolean active, Set<String> capabilities, BigDecimal limit) { Employee { if (id == null || id.isBlank() || id.length() > 64 || limit == null || limit.signum() < 0 || limit.compareTo(new BigDecimal("1000000000")) > 0 || limit.scale() > 2) throw new IllegalArgumentException("EMPLOYEE_SHAPE"); capabilities = Set.copyOf(Objects.requireNonNull(capabilities)); if (!Set.of("catalog", "request").containsAll(capabilities)) throw new IllegalArgumentException("EMPLOYEE_CAPABILITY"); } } // Created only by the authenticated caller after displaying this exact candidate. // It confirms declared slots, never procurement permission or approval. record Confirmation(String candidateId) {} record Item(String description, String catalogId, Integer quantity, String unit, BigDecimal amount, AmountKind amountKind, String currency, String purpose, Map<String, String> evidence) {} record Proposal(List<Item> items, List<String> ambiguities, String claimedApproval) {} record Decision(String action, Status status, List<String> reasons, List<String> missing, List<String> approvalRequirements) {} record Report(String candidateId, Proposal proposal, boolean confirmed, String declaredTotal, List<Decision> actions, String extractionState) { String explanation() { StringBuilder b = new StringBuilder("本次只给预检结果，未执行任何内部动作。"); if (candidateId != null) b.append(confirmed ? "申报候选已确认；确认不等于审批。" : "请先核对候选明细并确认本次 candidate_id。"); for (Decision d : actions) { b.append(&#x27;
