e.put(slot, span); } items.add(new Item(description, catalogId, quantity, unit, amount, amountKind, currency, purpose, java.util.Collections.unmodifiableMap(evidence))); } if (currencies.size() > 1) fail("MIXED_CURRENCIES"); List<String> ambiguities = new ArrayList<>(); for (Object a : list(root.get("ambiguities"), 0, 8)) { String s = text(a, 200); if (s == null) fail("NULL_AMBIGUITY"); ambiguities.add(s); } String claimed = text(root.get("claimed_approval"), 200); if (claimed != null && !raw.contains(claimed)) fail("APPROVAL_EVIDENCE"); return new Proposal(List.copyOf(items), List.copyOf(ambiguities), claimed); } static Map<?, ?> exactObject(Object v, Set<String> keys) { if (!(v instanceof Map<?, ?> m) || !m.keySet().equals(keys)) { throw new IllegalArgumentException("OBJECT_KEYS"); } return m; } static List<?> list(Object v, int min, int max) { if (!(v instanceof List<?> a) || a.size() < min || a.size() > max) throw new IllegalArgumentException("ARRAY_SIZE"); return a; } static String text(Object v, int max) { if (v == null) return null; if (!(v instanceof String s) || s.isBlank() || s.length() > max || !wellFormed(s)) throw new IllegalArgumentException("TEXT_SHAPE"); for (int i = 0; i < s.length(); i++) if (Character.isISOControl(s.charAt(i))) fail("TEXT_CONTROL"); return s; } static boolean wellFormed(String s) { for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (Character.isHighSurrogate(c)) { if (++i >= s.length() || !Character.isLowSurrogate(s.charAt(i))) return false; } else if (Character.isLowSurrogate(c)) return false; } return true; } static void fail(String code) { throw new IllegalArgumentException(code); } record CatalogEntry(String unit, boolean prohibited) {} static final Map<String, CatalogEntry> CATALOG = Map.of( "KB-1", new CatalogEntry("个", false), "MON-1", new CatalogEntry("台", false), "PAPER-1", new CatalogEntry("包", false), "DEMO-FORBIDDEN", new CatalogEntry("个", true)); static Report evaluate(Employee employee, Proposal proposal, String id, boolean confirmed, String state) { List<String> globalDeny = new ArrayList<>(); List<String> baseMissing = new ArrayList<>(); List<String> draftMissing = new ArrayList<>(); if (employee == null || !employee.active()) globalDeny.add("EMPLOYEE_UNAVAILABLE"); if (state.contains("INPUT_TOO_LONG") || state.contains("INPUT_CHARACTERS")) globalDeny.add("INPUT_REJECTED"); if (proposal == null) baseMissing.add("可核对的采购候选"); BigDecimal total = BigDecimal.ZERO; boolean totalKnown = proposal != null; if (proposal != null) { if (!proposal.ambiguities().isEmpty()) { baseMissing.add("消除候选歧义：" + String.join("；", proposal.ambiguities())); } for (int i = 0; i < proposal.items().size(); i++) { Item item = proposal.items().get(i); String prefix = "明细" + (i + 1) + "."; if (item.description() == null) baseMissing.add(prefix + "description"); CatalogEntry entry = item.catalogId() == null ? null : CATALOG.get(item.catalogId()); if (entry != null && entry.prohibited()) globalDeny.add("PROHIBITED_ITEM"); if (entry == null) draftMissing.add(prefix + "受信目录型号"); if (item.quantity() == null) draftMissing.add(prefix + "quantity"); if (item.unit() == null || entry != null && !entry.unit().equals(item.unit())) draftMissing.add(prefix + "目录单位或包装换算"); if (item.purpose() == null) draftMissing.add(prefix + "purpose"); if (!"CNY".equals(item.currency())) draftMissing.add(prefix + "明确人民币币种"); if (item.amount() == null || item.amountKind() != AmountKind.UNIT_PRICE) draftMissing.add(prefix + "申报单价（预算上限不能当单价）"); if (item.quantity() == null || item.amount() == null || item.amountKind() != AmountKind.UNIT_PRICE || !"CNY".equals(item.currency())) { totalKnown = false; } else total = total.add(item.amount().multiply(BigDecimal.valueOf(item.quantity()))); } if (!confirmed) draftMissing.add("核对并确认本次 candidate_id"); } List<Decision> actions = new ArrayList<>(); for (String action : ACTIONS) { boolean lookup = action.equals("lookup_catalog"); List<String> denies = new ArrayList<>(globalDeny); List<Strin