4)throw new IllegalArgumentException("COLUMN_COUNT");String name=c.get(0).strip(),type=c.get(1).strip(),currency=c.get(3).strip(); if(name.isEmpty()||name.length()>80||name.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("INVALID_CATEGORY"); if(!type.equals("INCOME")&&!type.equals("EXPENSE"))throw new IllegalArgumentException("INVALID_TYPE");BigDecimal money=amount(c.get(2),currency); var t=totals.computeIfAbsent(currency,k->new BigDecimal[]{new BigDecimal("0.00"),new BigDecimal("0.00")});int direction=type.equals("INCOME")?0:1;t[direction]=t[direction].add(money); if(direction==1)categories.computeIfAbsent(currency,k->new TreeMap<>()).merge(name,money,BigDecimal::add);good++; }catch(IllegalArgumentException e){bad.add(new Bad(row.line(),e.getMessage()));}} List<Summary> result=new ArrayList<>();for(var e:totals.entrySet()){var top=categories.getOrDefault(e.getKey(),Map.of()).entrySet().stream().map(x->new Category(x.getKey(),x.getValue())).sorted(Comparator.comparing(Category::expense).reversed().thenComparing(Category::name)).limit(3).toList();result.add(new Summary(e.getKey(),e.getValue()[0],e.getValue()[1],top));} return new Result(List.copyOf(result),List.copyOf(bad),good); } private static String q(String s){StringBuilder b=new StringBuilder(""");for(char c:s.toCharArray()){if(c==&#x27;"&#x27;||c==&#x27;\&#x27;)b.append(&#x27;\&#x27;).append(c);else if(c<32)b.append(String.format("\u%04x",(int)c));else b.append(c);}return b.append(&#x27;"&#x27;).toString();} public static String json(Result r){StringJoiner groups=new StringJoiner(",","[","]");for(var s:r.summaries()){StringJoiner top=new StringJoiner(",","[","]");for(var c:s.top3())top.add("{"category":"+q(c.name())+","amount":"+q(c.expense().toPlainString())+"}");groups.add("{"currency":"+q(s.currency())+","income":"+q(s.income().toPlainString())+","expense":"+q(s.expense().toPlainString())+","top3":"+top+"}");}StringJoiner bad=new StringJoiner(",","[","]");for(var b:r.rejected())